import{_ as e,o as a,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"后端问题 · 并发","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/problems/concurrency.md","filePath":"tech-system/backend/problems/concurrency.md"}'),l={name:"tech-system/backend/problems/concurrency.md"};function n(i,t,o,c,s,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="后端问题-·-并发" tabindex="-1">后端问题 · 并发 <a class="header-anchor" href="#后端问题-·-并发" aria-label="Permalink to “后端问题 · 并发”">​</a></h1><h2 id="我怎么看并发" tabindex="-1">我怎么看并发 <a class="header-anchor" href="#我怎么看并发" aria-label="Permalink to “我怎么看并发”">​</a></h2><p>并发不是「开越多越好」，而是：<strong>把共享资源的冲突和资源上限管住。</strong></p><ul><li>Java：线程池有界；别在请求线程里做无界任务堆积</li><li>Node：别堵事件循环</li><li>Go：Goroutine 也要有退出与限流</li><li>Python：I/O 可用 async；CPU 别迷信多线程</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to “常见坑”">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>常见根因</th><th>处理方向</th></tr></thead><tbody><tr><td>接口越来越慢</td><td>池满、队列堆积、下游超时未设</td><td>限流、超时、隔离池</td></tr><tr><td>CPU 打满</td><td>死循环、频繁 GC、重计算</td><td>抓栈/剖析；拆任务</td></tr><tr><td>偶现数据错乱</td><td>共享可变状态无同步</td><td>加锁、改不可变、单线程消费</td></tr><tr><td>异步任务丢了</td><td>进程挂了、只在内存队列</td><td>落库/MQ；可恢复</td></tr></tbody></table><h2 id="我的默认策略" tabindex="-1">我的默认策略 <a class="header-anchor" href="#我的默认策略" aria-label="Permalink to “我的默认策略”">​</a></h2><ol><li>同步请求尽量短；重活进队列 + 状态机（AI 生成就是这个思路）</li><li>一切远程调用有超时</li><li>线程池/连接池参数写清楚，禁止无界</li></ol><p>细题可对照就业指南里的并发章节。</p>',9)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
